('mixed', 'writing', 'word_order', 'Susun kalimat yang menunjukkan ajakan belajar bersama.', NULL, '["وَنَتَذَاكَرُ","فِي","التَّعَلُّمِ","مَعًا","نَتَعَاوَنُ"]'::jsonb, 'نَتَعَاوَنُ فِي التَّعَلُّمِ وَنَتَذَاكَرُ مَعًا', 'Kalimat menyatakan kerja sama dalam belajar dan mengulang pelajaran bersama.', NULL, 88, true),
('mixed', 'reading', 'multiple_choice', 'Apa pesan utama dari pernyataan الصَّدَاقَةُ فِي سَبِيلِ الْعِلْمِ شَيْءٌ جَمِيلٌ?', NULL, '["Persahabatan dapat mendukung kegiatan mencari ilmu","Persahabatan hanya penting ketika bermain","Belajar sebaiknya dilakukan tanpa teman"]'::jsonb, 'Persahabatan dapat mendukung kegiatan mencari ilmu', 'Tokoh menilai persahabatan dalam menuntut ilmu sebagai hal yang baik.', NULL, 89, true),
('mixed', 'reading', 'multiple_choice', 'Kesimpulan paling tepat dari dialog Faris dan Zaid adalah ...', NULL, '["Dua siswa baru saling mengenal, bertukar pandangan tentang belajar, dan bersepakat bekerja sama","Dua siswa bertengkar karena berbeda asal daerah","Seorang guru menjelaskan aturan sekolah kepada seluruh kelas"]'::jsonb, 'Dua siswa baru saling mengenal, bertukar pandangan tentang belajar, dan bersepakat bekerja sama', 'Dialog memuat perkenalan, pendapat tentang sekolah, mata pelajaran, dan ajakan bekerja sama.', NULL, 90, true),
('mixed', 'reading', 'multiple_choice', 'Dalam bacaan tentang Abdullah, ia belajar di الصف الأول. Informasi yang tepat adalah ...', NULL, '["Abdullah berada di kelas satu sekolah menengah","Abdullah mengajar di sekolah menengah","Abdullah sudah menjadi alumni"]'::jsonb, 'Abdullah berada di kelas satu sekolah menengah', 'Teks menyebutkan أَدْرُسُ حَالِيًّا فِي الصَّفِّ الْأَوَّلِ.', NULL, 91, true),
('mixed', 'listening', 'multiple_choice', 'Dengarkan alasan Abdullah menyukai Bahasa Arab. Alasan yang sesuai dengan teks adalah ...', NULL, '["Bahasa Arab merupakan bahasa Al-Qur''an dan hadis Nabi","Bahasa Arab digunakan hanya untuk olahraga","Bahasa Arab tidak berkaitan dengan pelajaran lain"]'::jsonb, 'Bahasa Arab merupakan bahasa Al-Qur''an dan hadis Nabi', 'Dalam bacaan, Abdullah menyukai Bahasa Arab karena merupakan bahasa Al-Qur''an dan hadis Nabi.', 'أُحِبُّ دِرَاسَةَ اللُّغَةِ الْعَرَبِيَّةِ لِأَنَّهَا لُغَةُ الْقُرْآنِ الْكَرِيمِ', 92, true),
('mixed', 'vocabulary', 'matching_pairs', 'Jodohkan informasi dari bacaan Abdullah dengan rincian yang benar.', NULL, '[{"id":"p1","arabic":"أَبِي","meaning":"Bekerja sebagai guru"},{"id":"p2","arabic":"أُمِّي","meaning":"Ibu rumah tangga"},{"id":"p3","arabic":"أُسْرَتِي","meaning":"Tinggal di desa dekat kota"},{"id":"p4","arabic":"أَخْلَاقُ الْأَوْلَادِ","meaning":"Dibina dengan kasih sayang dan kesabaran"}]'::jsonb, 'ALL_MATCHED', 'Jawaban diambil dari paragraf tentang keluarga Abdullah.', NULL, 93, true),
('mixed', 'writing', 'word_order', 'Susun kalimat yang menjelaskan tempat tinggal Abdullah.', NULL, '["قَرْيَةٍ","مَعَ","أُسْرَتِي","أَعِيشُ","فِي"]'::jsonb, 'أَعِيشُ مَعَ أُسْرَتِي فِي قَرْيَةٍ', 'Kalimat menyatakan bahwa Abdullah tinggal bersama keluarganya di sebuah desa.', NULL, 94, true),
('mixed', 'speaking', 'speaking_repeat', 'Ulangi kalimat tentang kesukaan belajar Bahasa Arab.', 'أُحِبُّ دِرَاسَةَ اللُّغَةِ الْعَرَبِيَّةِ', '[]'::jsonb, 'أُحِبُّ دِرَاسَةَ اللُّغَةِ الْعَرَبِيَّةِ', 'Kalimat ini berarti saya menyukai pelajaran Bahasa Arab.', 'أُحِبُّ دِرَاسَةَ اللُّغَةِ الْعَرَبِيَّةِ', 95, true),
('mixed', 'vocabulary', 'image_choice', 'Pilih ilustrasi yang paling sesuai dengan kegiatan يَقْرَأُ الْكُتُبَ.', NULL, '[{"label":"Membaca buku","emoji":"📚"},{"label":"Bermain bola","emoji":"⚽"},{"label":"Memasak","emoji":"🍲"},{"label":"Berkendara","emoji":"🚲"}]'::jsonb, 'Membaca buku', 'يَقْرَأُ الْكُتُبَ berarti membaca buku-buku.', NULL, 96, true),
('mixed', 'reading', 'multiple_choice', 'Bacaan menyebutkan bahwa ayah Abdullah bekerja sebagai مُعَلِّمًا. Kesimpulan yang benar adalah ...', NULL, '["Ayah Abdullah berprofesi sebagai guru","Ayah Abdullah berprofesi sebagai dokter","Ayah Abdullah adalah siswa"]'::jsonb, 'Ayah Abdullah berprofesi sebagai guru', 'مُعَلِّمٌ berarti guru.', NULL, 97, true),
('mixed', 'listening', 'listen_word_order', 'Dengarkan lalu susun pernyataan tentang manfaat belajar.', NULL, '["أَتَعَلَّمُهُ","مِنْ","كُلِّ","مَا","أَسْتَفِيدُ"]'::jsonb, 'أَسْتَفِيدُ مِنْ كُلِّ مَا أَتَعَلَّمُهُ', 'Kalimat berarti saya mengambil manfaat dari semua yang saya pelajari.', 'أَسْتَفِيدُ مِنْ كُلِّ مَا أَتَعَلَّمُهُ', 98, true),
('mixed', 'reading', 'multiple_choice', 'Dalam bacaan Khalid, ia berusia tujuh belas tahun. Kalimat Arab yang menunjukkan informasi itu adalah ...', NULL, '["عُمْرُهُ سَبْعَ عَشْرَةَ سَنَةً","هُوَ فِي الْمَكْتَبَةِ","أَبُوهُ مُوَظَّفٌ"]'::jsonb, 'عُمْرُهُ سَبْعَ عَشْرَةَ سَنَةً', 'عُمْرُهُ berarti umurnya, sedangkan سَبْعَ عَشْرَةَ berarti tujuh belas.', NULL, 99, true),
('mixed', 'vocabulary', 'matching_pairs', 'Pasangkan kosakata yang digunakan dalam bacaan dengan artinya.', NULL, '[{"id":"p1","arabic":"الْقِرَاءَةُ","meaning":"Membaca"},{"id":"p2","arabic":"الْبَحْثُ","meaning":"Penelitian"},{"id":"p3","arabic":"التَّكْنُولُوجِيَا","meaning":"Teknologi"},{"id":"p4","arabic":"التَّارِيخُ","meaning":"Sejarah"}]'::jsonb, 'ALL_MATCHED', 'Makna kata membantu memahami kegiatan dan mata pelajaran dalam bacaan.', NULL, 100, true),
('mixed', 'writing', 'word_order', 'Susun kalimat tentang Khalid yang rajin belajar.', NULL, '["فِي","وَمُجْتَهِدٌ","خَالِدٌ","دِرَاسَتِهِ","طَالِبٌ","نَشِيطٌ"]'::jsonb, 'خَالِدٌ طَالِبٌ نَشِيطٌ وَمُجْتَهِدٌ فِي دِرَاسَتِهِ', 'Kalimat berarti Khalid adalah siswa yang aktif dan rajin dalam belajarnya.', NULL, 101, true),
('mixed', 'speaking', 'speaking_repeat', 'Ulangi kalimat tentang belajar dan memanfaatkan waktu.', 'نَتَعَلَّمُ حُبَّ الْعِلْمِ وَحُسْنَ اسْتِغْلَالِ الْوَقْتِ', '[]'::jsonb, 'نَتَعَلَّمُ حُبَّ الْعِلْمِ وَحُسْنَ اسْتِغْلَالِ الْوَقْتِ', 'Kalimat ini menekankan cinta ilmu dan penggunaan waktu dengan baik.', 'نَتَعَلَّمُ حُبَّ الْعِلْمِ وَحُسْنَ اسْتِغْلَالِ الْوَقْتِ', 102, true),
('mixed', 'vocabulary', 'image_choice', 'Pilih gambar yang paling sesuai dengan kegiatan يَلْعَبُ كُرَةَ الْقَدَمِ.', NULL, '[{"label":"Bermain sepak bola","emoji":"⚽"},{"label":"Membaca buku","emoji":"📚"},{"label":"Belajar di kelas","emoji":"🏫"},{"label":"Menulis surat","emoji":"✉️"}]'::jsonb, 'Bermain sepak bola', 'Ungkapan tersebut berarti bermain sepak bola.', NULL, 103, true),
('mixed', 'reading', 'multiple_choice', 'Khalid menyukai sejarah karena ...', NULL, '["Sejarah mengenalkan keadaan bangsa-bangsa terdahulu","Sejarah mengajarkan cara bermain bola","Sejarah hanya membahas nama sekolah"]'::jsonb, 'Sejarah mengenalkan keadaan bangsa-bangsa terdahulu', 'Teks menyatakan bahwa sejarah membantu mengenal keadaan umat terdahulu.', NULL, 104, true),
('mixed', 'writing', 'multiple_choice', 'Susunlah gagasan menjadi paragraf perkenalan yang paling runtut. Pilih urutan yang benar.', NULL, '["Nama dan identitas → asal/tempat tinggal → keluarga → kegiatan belajar dan minat","Kegiatan belajar → salam perpisahan → nama → pertanyaan kabar","Tempat tinggal → jawaban salam → nama orang lain → umur tanpa konteks"]'::jsonb, 'Nama dan identitas → asal/tempat tinggal → keluarga → kegiatan belajar dan minat', 'Urutan tersebut menyajikan informasi dari identitas dasar menuju rincian kehidupan dan minat.', NULL, 105, true)
) as v(mode, skill, question_type, prompt, prompt_arabic, options, correct_answer, explanation, audio_text, sort_order, is_published)
where l.slug = 'at-taaruf'
on conflict (lesson_id, mode, sort_order) do update set
  skill = excluded.skill,
  question_type = excluded.question_type,
  prompt = excluded.prompt,
  prompt_arabic = excluded.prompt_arabic,
  options = excluded.options,
  correct_answer = excluded.correct_answer,
  explanation = excluded.explanation,
  audio_text = excluded.audio_text,
  is_published = excluded.is_published;

do $$
declare
  v_count integer;
begin
  select count(*) into v_count
  from public.questions q
  join public.lessons l on l.id = q.lesson_id
  where l.slug = 'at-taaruf'
    and q.mode = 'mixed'
    and q.is_published = true
    and q.sort_order between 1 and 105;

  if v_count <> 105 then
    raise exception 'Bank soal ARABEEZA harus berjumlah 105, ditemukan %', v_count;
  end if;
end $$;

commit;
